{
  "merge_policy": "auto",
  "environment": {
    "setup_commands": []
  },
  "checks": {
    "commands": [
      "./scripts/scan-secrets.sh",
      "bun install --frozen-lockfile",
      "bun run typecheck",
      "bun run synth",
      "bun run test"
    ],
    "secrets": []
  },
  "deploy": {
    "targets": [
      {
        "name": "release",
        "on": "merge",
        "commands": [
          "./scripts/release.sh"
        ]
      }
    ],
    "secrets": []
  },
  "tools": {
    "secrets": []
  },
  "agents": {
    "orchestrator": {
      "max_iterations": 100
    },
    "engineer": {
      "max_iterations": 200
    },
    "reviewer": {
      "max_iterations": 30
    }
  },
  "labels": {
    "in_progress": "atoma/in-progress",
    "sub_issue": "atoma/sub-issue",
    "launched": "atoma/launched"
  },
  "auto_triggers": [
    {
      "event": "pull_request.opened",
      "agent": "reviewer"
    },
    {
      "event": "pull_request.synchronize",
      "agent": "reviewer"
    },
    {
      "event": "pull_request.ready_for_review",
      "agent": "reviewer"
    },
    {
      "event": "pull_request_review.submitted",
      "agent": "engineer",
      "condition": "changes_requested"
    },
    {
      "event": "issue_comment.created",
      "agent": "$dispatch_agent",
      "condition": "atoma:dispatch"
    }
  ],
  "workflows": {
    "ci": "ci.yml",
    "cd": "cd.yml"
  },
  "governed_paths": [
    ".github/**",
    "scripts/**"
  ]
}
